# Generates assistant/resources/catalog-formulas.json for BeautyWallet catalog ids.
# basis=inci_sourced: INCI copied from a public product page (secondary aggregator or retailer);
#   still NOT human-verified against the Iranian-market pack.
# basis=declared_name: only what the product name/label claim states (e.g. "Azelaic Acid 10%").
import json, sys
CHECKED = '2026-10-13'

def a(cls, name, pct=None, declared=False):
    d = {'cls': cls, 'name': name}
    if pct is not None: d['pct'] = pct
    if declared: d['declared'] = True
    return d

P = []
def add(id, role, texture, actives=(), claims=(), flags=(), basis='inci_sourced', sources=(), inci='', finish=None, spf=None, filters=None, note='', rinse=None):
    rinse_off = rinse if rinse is not None else role in ('cleanser', 'micellar', 'mask')
    e = {'id': id, 'role': role, 'rinseOff': rinse_off, 'texture': texture, 'actives': list(actives), 'claims': list(claims), 'flags': list(flags), 'basis': basis, 'sources': list(sources), 'checked': CHECKED}
    if finish: e['finish'] = finish
    if spf: e['spf'] = spf
    if filters: e['filters'] = filters
    if inci: e['inci'] = inci
    if note: e['note'] = note
    P.append(e)

